toolArgs.file_text:
@page "/board"
@using sv_03963e28b1b848f9bfe28d387f3b2bef
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (_loading)
{
    <div class="board-loading">Loading tasks...</div>
}
else if (_error is not null)
{
    <div class="board-error">
        <p>Failed to load tasks: @_error</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Tasks="_tasks" />
    <BoardSearchBar @bind-SearchText="_searchText" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="GetFilteredTasks("To Do")"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                     OnTaskCreated="HandleTaskCreated" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="GetFilteredTasks("In Progress")"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                     OnMoveRight="@(id => MoveTask(id, "Done"))"
                     OnTaskCreated="HandleTaskCreated" />

        <BoardColumn ColumnName="Done"
                     Tasks="GetFilteredTasks("Done")"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                     OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    private List<TaskItem> _tasks = new();
    private string _searchText = string.Empty;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _loading = true;
        _error = null;
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = _tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _tasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                _tasks[_tasks.IndexOf(task)] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            // The service creates with default status; update to match the column if needed
            if (newTask.Status != data.Status)
            {
                await TaskService.UpdateTaskStatusAsync(newTask.Id, data.Status);
                newTask = newTask with { Status = data.Status };
            }
            _tasks.Add(newTask);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

